// Editing in the workbook view: the cell editor, undo and redo, the
// clipboard, inserting and deleting rows and columns, read-only mode.
//
// Pointer positions are written out by hand from the default sizes of a sheet
// (header 72 x 22, columns 64 wide, rows 20 high) instead of being asked from
// the engine's own layout. Every workbook is generated by code.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const MAX_ROWS = 1048576;
const MAX_COLS = 16384;
const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;
const MOUSE_ONLY = 'mouse input is covered by the desktop projects';
const TOUCH_ONLY = 'touch input is covered by the mobile projects';

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;
const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/**
 * "Data": A1=1, B1=2, C1=A1+B1, A2="hello", A3=10, a row 12 that is twice as
 * high as the others and a merged D5:E6. "Other": A1 refers to Data!A3.
 */
const editWorkbook = once(() =>
  buildXlsx({
    sheets: [
      {
        name: 'Data',
        xml: worksheetXml(
          '<sheetData>' +
            `<row r="1">${num('A1', 1)}${num('B1', 2)}<c r="C1"><f>A1+B1</f><v>3</v></c></row>` +
            `<row r="2">${str('A2', 'hello')}</row>` +
            `<row r="3">${num('A3', 10)}</row>` +
            `<row r="5">${num('D5', 5)}</row>` +
            `<row r="12" ht="30" customHeight="1">${num('A12', 12)}</row>` +
            '</sheetData><mergeCells count="1"><mergeCell ref="D5:E6"/></mergeCells>',
        ),
      },
      { name: 'Other', xml: worksheetXml('<sheetData><row r="1"><c r="A1"><f>Data!A3</f><v>10</v></c></row></sheetData>') },
    ],
  }),
);

const frozenWorkbook = once(() =>
  buildXlsx({
    sheets: [
      {
        name: 'Frozen',
        xml: worksheetXml(
          '<sheetViews><sheetView workbookViewId="0"><pane xSplit="1" ySplit="2" topLeftCell="B3" activePane="bottomRight" state="frozen"/>' +
            '<selection pane="bottomRight" activeCell="B3" sqref="B3"/></sheetView></sheetViews>' +
            `<sheetData><row r="1">${num('A1', 1)}</row></sheetData>`,
        ),
      },
    ],
  }),
);

const BIG_ROWS = 100_000;
const bigWorkbook = once(() => {
  const rows: string[] = [];
  for (let r = 1; r <= BIG_ROWS; r++) rows.push(`<row r="${r}">${num(`A${r}`, r)}<c r="B${r}"><f>A${r}*2</f><v>${r * 2}</v></c></row>`);
  return buildXlsx({ sheets: [{ name: 'Big', xml: worksheetXml(`<sheetData>${rows.join('')}</sheetData>`) }] });
});

interface MountOptions {
  sheet?: number;
  locale?: string;
  readOnly?: boolean;
}

async function mount(page: Page, bytes: Uint8Array, options: MountOptions = {}): Promise<void> {
  await page.goto('/e2e/pages/view.html');
  await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountView(data, options);
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

function selection(page: Page): Promise<{ active: string; range: string }> {
  return page.evaluate(() => {
    const api = (window as any).BymOffice;
    const s = (window as any).__view.selection;
    return { active: api.cellName(s.active.row, s.active.col), range: api.rangeName(s.range) };
  });
}

const rawRange = (page: Page): Promise<{ top: number; left: number; bottom: number; right: number }> =>
  page.evaluate(() => (window as any).__view.selection.range);

const select = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    (window as any).__view.select(api.parseRange(ref));
  }, ref);

interface CellInfo {
  kind?: string;
  value?: number | string | boolean | null;
  formula?: string;
  shown: string;
}

/** A cell of the model as plain data, with the text the grid shows for it. */
function cell(page: Page, ref: string, sheet = 0): Promise<CellInfo> {
  return page.evaluate(
    ([ref, sheet]) => {
      const api = (window as any).BymOffice;
      const view = (window as any).__view;
      const at = api.parseCellRef(ref);
      const found = api.getCell(view.workbook.sheets[sheet as number], at.row, at.col);
      const shown = api.cellDisplayText(view.workbook, found, api.getLocale((window as any).__locale || 'en-US'));
      return found ? { kind: found.kind, value: found.value, formula: found.formula ? found.formula.text : undefined, shown } : { shown };
    },
    [ref, sheet] as [string, number],
  );
}

const events = (page: Page, type?: string): Promise<any[]> =>
  page.evaluate((type) => (window as any).__events.filter((event: any) => !type || event.type === type), type);

const view = <T>(page: Page, run: string): Promise<T> => page.evaluate(`(() => { const view = window.__view; return ${run}; })()`) as Promise<T>;

interface Box {
  x: number;
  y: number;
  width: number;
  height: number;
}

const canvasBox = async (page: Page): Promise<Box> => (await page.locator('.bym-canvas').boundingBox())!;

/** A point inside a cell of an unscrolled sheet with default sizes. */
function pointIn(box: Box, row: number, col: number, fx = 0.5, fy = 0.5): { x: number; y: number } {
  return { x: box.x + HEADER_WIDTH + COLUMN_WIDTH * (col + fx), y: box.y + HEADER_HEIGHT + ROW_HEIGHT * (row + fy) };
}

const input = (page: Page) => page.locator('.bym-input');
const live = (page: Page) => page.locator('.bym-view [aria-live]');

async function focusGrid(page: Page): Promise<void> {
  await input(page).focus();
  await expect(input(page)).toBeFocused();
}

/** Where the editor is and whether it can be seen. */
function editorState(page: Page): Promise<{ editing: boolean; value: string; opacity: string; mode: string | null; box: Box }> {
  return page.evaluate(() => {
    const element = document.querySelector('.bym-input') as HTMLTextAreaElement;
    const rect = element.getBoundingClientRect();
    return {
      editing: (window as any).__view.isEditing,
      value: element.value,
      opacity: getComputedStyle(element).opacity,
      mode: element.getAttribute('inputmode'),
      box: { x: rect.left, y: rect.top, width: rect.width, height: rect.height },
    };
  });
}

/** Fires a clipboard event at the input the way the browser does for Ctrl+C/X/V, and returns what ended up on the clipboard. */
function clipboardEvent(page: Page, type: 'copy' | 'cut' | 'paste', text?: string, html?: string): Promise<{ prevented: boolean; text: string; html: string }> {
  return page.evaluate(
    ([type, text, html]) => {
      const data = new DataTransfer();
      if (text !== null) data.setData('text/plain', text);
      if (html !== null) data.setData('text/html', html);
      let event: Event | undefined;
      try {
        event = new ClipboardEvent(type, { clipboardData: data, bubbles: true, cancelable: true });
      } catch {
        event = undefined;
      }
      // Some browsers give a scripted clipboard event a clipboard of their own instead of the one passed in.
      if (!event || (event as ClipboardEvent).clipboardData !== data) {
        event = new Event(type, { bubbles: true, cancelable: true });
        Object.defineProperty(event, 'clipboardData', { value: data });
      }
      document.querySelector('.bym-input')!.dispatchEvent(event);
      return { prevented: event.defaultPrevented, text: data.getData('text/plain'), html: data.getData('text/html') };
    },
    [type, text === undefined ? null : text, html === undefined ? null : html] as [string, string | null, string | null],
  );
}

test.describe('typing into a cell', () => {
  test('typing starts the editor over the cell; Enter writes and moves down', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B3');
    let editor = await editorState(page);
    expect(editor).toMatchObject({ editing: false, opacity: '0', mode: 'none' });
    expect(editor.box.width).toBeLessThanOrEqual(1);

    await page.keyboard.type('42');
    editor = await editorState(page);
    expect(editor).toMatchObject({ editing: true, value: '42', opacity: '1', mode: 'text' });
    // The editor covers B3 and its grid lines, in CSS pixels whatever the device pixel ratio.
    const box = await canvasBox(page);
    expect(Math.round(editor.box.x - box.x)).toBe(HEADER_WIDTH + COLUMN_WIDTH - 1);
    expect(Math.round(editor.box.y - box.y)).toBe(HEADER_HEIGHT + 2 * ROW_HEIGHT - 1);
    expect(editor.box.width).toBeGreaterThanOrEqual(COLUMN_WIDTH + 1);
    expect(editor.box.width).toBeLessThan(COLUMN_WIDTH + 12);
    expect(editor.box.height).toBeGreaterThanOrEqual(ROW_HEIGHT + 1);
    expect(editor.box.height).toBeLessThan(ROW_HEIGHT + 8);
    // Nothing is written before the edit is confirmed.
    expect((await cell(page, 'B3')).value).toBeUndefined();
    expect(await events(page, 'change')).toEqual([]);

    await page.keyboard.press('Enter');
    expect(await cell(page, 'B3')).toMatchObject({ kind: 'number', value: 42, shown: '42' });
    expect(await selection(page)).toEqual({ active: 'B4', range: 'B4' });
    expect(await editorState(page)).toMatchObject({ editing: false, opacity: '0', mode: 'none' });
    expect(await events(page, 'change')).toEqual([{ type: 'change', sheets: [0] }]);
    await expect(input(page)).toBeFocused();
    await page.keyboard.press('ArrowUp');
    await expect(live(page)).toHaveText('B3 42');
  });

  test('typing replaces the content; F2 edits it', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'A2');
    await page.keyboard.type('x');
    expect((await editorState(page)).value).toBe('x');
    await page.keyboard.press('Escape');
    expect(await editorState(page)).toMatchObject({ editing: false, opacity: '0' });
    expect((await cell(page, 'A2')).value).toBe('hello');
    expect(await events(page, 'change')).toEqual([]);
    await expect(input(page)).toBeFocused();

    await page.keyboard.press('F2');
    expect(await editorState(page)).toMatchObject({ editing: true, value: 'hello', opacity: '1' });
    // The caret is at the end, and the arrow keys move it instead of the selection.
    await page.keyboard.type('!');
    await page.keyboard.press('ArrowLeft');
    await page.keyboard.press('ArrowLeft');
    await page.keyboard.type('-');
    expect((await editorState(page)).value).toBe('hell-o!');
    expect(await selection(page)).toEqual({ active: 'A2', range: 'A2' });
    await page.keyboard.press('ArrowDown');
    expect(await selection(page)).toEqual({ active: 'A2', range: 'A2' });
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A2')).value).toBe('hell-o!');

    // Confirming an edit that changed nothing is not a change.
    await select(page, 'A3');
    await page.keyboard.press('F2');
    expect((await editorState(page)).value).toBe('10');
    await page.keyboard.press('Enter');
    expect(await events(page, 'change')).toHaveLength(1);
    expect(await view(page, 'view.history.canUndo')).toBe(true);
    expect(await selection(page)).toEqual({ active: 'A4', range: 'A4' });
  });

  test('a double click edits the cell with its content', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    const a2 = pointIn(box, 1, 0);
    await page.mouse.dblclick(a2.x, a2.y);
    expect(await editorState(page)).toMatchObject({ editing: true, value: 'hello' });
    await expect(input(page)).toBeFocused();
    await page.keyboard.type(' there');

    // A click on another cell writes the edit and selects that cell.
    const c4 = pointIn(box, 3, 2);
    await page.mouse.click(c4.x, c4.y);
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'A2')).value).toBe('hello there');
    expect(await selection(page)).toEqual({ active: 'C4', range: 'C4' });

    // A double click on a header edits nothing.
    await page.mouse.dblclick(box.x + HEADER_WIDTH / 2, a2.y);
    expect(await view(page, 'view.isEditing')).toBe(false);
  });

  test('Enter, Shift+Enter, Tab and Shift+Tab write and move', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'C8');
    await page.keyboard.type('a');
    await page.keyboard.press('Tab');
    expect(await selection(page)).toEqual({ active: 'D8', range: 'D8' });
    await page.keyboard.type('b');
    await page.keyboard.press('Shift+Tab');
    expect(await selection(page)).toEqual({ active: 'C8', range: 'C8' });
    await page.keyboard.type('c');
    await page.keyboard.press('Shift+Enter');
    expect(await selection(page)).toEqual({ active: 'C7', range: 'C7' });
    await page.keyboard.type('d');
    await page.keyboard.press('Enter');
    expect(await selection(page)).toEqual({ active: 'C8', range: 'C8' });
    expect([(await cell(page, 'C8')).value, (await cell(page, 'D8')).value, (await cell(page, 'C7')).value]).toEqual(['c', 'b', 'd']);
    await expect(input(page)).toBeFocused();
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect(await events(page, 'change')).toHaveLength(4);
  });

  test('Tab leaves the grid while no cell is edited', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await page.keyboard.press('Tab');
    await expect(input(page)).not.toBeFocused();
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect(await selection(page)).toEqual({ active: 'A1', range: 'A1' });
    expect(await events(page)).toEqual([]);
  });

  test('Alt+Enter adds a line and the editor grows', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.keyboard.type('one');
    const single = (await editorState(page)).box.height;
    await page.keyboard.press('Alt+Enter');
    expect(await view(page, 'view.isEditing')).toBe(true);
    await page.keyboard.type('two');
    const editor = await editorState(page);
    expect(editor.value).toBe('one\ntwo');
    expect(editor.box.height).toBeGreaterThan(single + 8);
    await page.keyboard.press('Enter');
    expect((await cell(page, 'B8')).value).toBe('one\ntwo');
  });

  test('long text widens the editor up to the edge of the grid', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.keyboard.type('a fairly long piece of text');
    const box = await canvasBox(page);
    let editor = await editorState(page);
    expect(editor.box.width).toBeGreaterThan(COLUMN_WIDTH + 30);
    await page.keyboard.type(' that goes on and on and on and on and on and on and on and on and on and on and on and on and on and on and on and on');
    editor = await editorState(page);
    expect(editor.box.x + editor.box.width).toBeLessThanOrEqual(box.x + box.width + 0.5);
    expect(Math.round(editor.box.x - box.x)).toBe(HEADER_WIDTH + COLUMN_WIDTH - 1);
    await page.keyboard.press('Escape');
  });

  test('a merged cell is edited as a whole', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'E6');
    expect(await selection(page)).toEqual({ active: 'D5', range: 'D5:E6' });
    await page.keyboard.press('F2');
    const box = await canvasBox(page);
    const editor = await editorState(page);
    expect(editor.value).toBe('5');
    expect(Math.round(editor.box.x - box.x)).toBe(HEADER_WIDTH + 3 * COLUMN_WIDTH - 1);
    expect(Math.round(editor.box.y - box.y)).toBe(HEADER_HEIGHT + 4 * ROW_HEIGHT - 1);
    // Both columns and both rows, or as much of them as a narrow screen shows.
    const room = box.width - (HEADER_WIDTH + 3 * COLUMN_WIDTH - 1);
    expect(editor.box.width).toBeGreaterThanOrEqual(Math.min(2 * COLUMN_WIDTH + 1, room) - 0.5);
    expect(editor.box.x + editor.box.width).toBeLessThanOrEqual(box.x + box.width + 0.5);
    expect(editor.box.height).toBeGreaterThanOrEqual(2 * ROW_HEIGHT + 1);
    await page.keyboard.type('5');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'D5')).value).toBe(55);
    expect(await selection(page)).toEqual({ active: 'D7', range: 'D7' });
  });

  test('with frozen panes the editor sits on the frozen cell', async ({ page }) => {
    await mount(page, await frozenWorkbook());
    await focusGrid(page);
    await view(page, 'view.scrollTo(200, 30)');
    await select(page, 'A2');
    await page.keyboard.press('F2');
    const box = await canvasBox(page);
    const editor = await editorState(page);
    expect(editor).toMatchObject({ editing: true, opacity: '1' });
    expect(Math.round(editor.box.x - box.x)).toBe(HEADER_WIDTH - 1);
    expect(Math.round(editor.box.y - box.y)).toBe(HEADER_HEIGHT + ROW_HEIGHT - 1);
    await page.keyboard.press('Escape');
  });
});

test.describe('what typed text becomes', () => {
  test('numbers, dates and percentages in Turkish', async ({ page }) => {
    await mount(page, await editWorkbook(), { locale: 'tr' });
    await page.evaluate(() => ((window as any).__locale = 'tr'));
    await focusGrid(page);
    await select(page, 'B8');
    for (const text of ['12,5', '15.03.2024', '%25', '1.234,5', 'merhaba']) {
      await page.keyboard.type(text);
      await page.keyboard.press('Enter');
    }
    expect(await cell(page, 'B8')).toMatchObject({ kind: 'number', value: 12.5, shown: '12,5' });
    expect(await cell(page, 'B9')).toMatchObject({ kind: 'number', value: 45366, shown: '15.03.2024' });
    expect(await cell(page, 'B10')).toMatchObject({ kind: 'number', value: 0.25, shown: '25%' });
    expect(await cell(page, 'B11')).toMatchObject({ kind: 'number', value: 1234.5, shown: '1.234,50' });
    expect(await cell(page, 'B12')).toMatchObject({ kind: 'string', value: 'merhaba' });
    await select(page, 'B9');
    await expect(live(page)).toHaveText('B9 15.03.2024');
    await select(page, 'B8');
    await expect(live(page)).toHaveText('B8 12,5');
    // The editor offers the value back the way it is typed in this language.
    await page.keyboard.press('F2');
    expect((await editorState(page)).value).toBe('12,5');
    await page.keyboard.press('Escape');
  });

  test('numbers, dates and percentages in English', async ({ page }) => {
    await mount(page, await editWorkbook(), { locale: 'en-US' });
    await focusGrid(page);
    await select(page, 'B8');
    for (const text of ['12.5', '3/15/2024', '25%', '1,234.5', '12,5']) {
      await page.keyboard.type(text);
      await page.keyboard.press('Enter');
    }
    expect(await cell(page, 'B8')).toMatchObject({ kind: 'number', value: 12.5, shown: '12.5' });
    expect(await cell(page, 'B9')).toMatchObject({ kind: 'number', value: 45366, shown: '3/15/2024' });
    expect(await cell(page, 'B10')).toMatchObject({ kind: 'number', value: 0.25, shown: '25%' });
    expect(await cell(page, 'B11')).toMatchObject({ kind: 'number', value: 1234.5, shown: '1,234.50' });
    await select(page, 'B10');
    await expect(live(page)).toHaveText('B10 25%');
  });

  test('a formula is kept as a formula and shown as its result', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B2');
    await page.keyboard.type('=A1*2');
    await page.keyboard.press('Enter');
    expect(await cell(page, 'B2')).toMatchObject({ formula: 'A1*2', shown: '2' });
    await page.keyboard.press('ArrowUp');
    await expect(live(page)).toHaveText('B2 2');
    await page.keyboard.press('F2');
    expect((await editorState(page)).value).toBe('=A1*2');
    await page.keyboard.press('Escape');
  });
});

test.describe('delete, undo and redo', () => {
  test('Delete empties the range; undo and redo by keyboard', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'A1:C3');
    await page.keyboard.press('Delete');
    expect([(await cell(page, 'A1')).value, (await cell(page, 'C1')).formula, (await cell(page, 'A2')).value, (await cell(page, 'A3')).value]).toEqual([
      undefined,
      undefined,
      undefined,
      undefined,
    ]);
    expect(await events(page, 'change')).toHaveLength(1);
    // Nothing left to delete: no change, no undo step.
    await page.keyboard.press('Backspace');
    expect(await events(page, 'change')).toHaveLength(1);

    await select(page, 'F9');
    await page.keyboard.press('Control+z');
    expect(await cell(page, 'A1')).toMatchObject({ value: 1 });
    expect(await cell(page, 'C1')).toMatchObject({ formula: 'A1+B1', value: 3 });
    expect((await cell(page, 'A2')).value).toBe('hello');
    // The selection of the time comes back with the content.
    expect(await selection(page)).toEqual({ active: 'A1', range: 'A1:C3' });
    expect(await view(page, '[view.history.canUndo, view.history.canRedo]')).toEqual([false, true]);

    await page.keyboard.press('Control+y');
    expect((await cell(page, 'A1')).value).toBeUndefined();
    await page.keyboard.press('Control+z');
    await page.keyboard.press('Control+Shift+z');
    expect((await cell(page, 'A1')).value).toBeUndefined();
    await page.keyboard.press('Control+z');
    expect((await cell(page, 'A1')).value).toBe(1);
    // Nothing more to undo.
    await page.keyboard.press('Control+z');
    expect(await events(page, 'change')).toHaveLength(6);
    await expect(input(page)).toBeFocused();
  });

  test('undo returns to the sheet and selection of the change', async ({ page }) => {
    await mount(page, await editWorkbook());
    await view(page, 'view.select({ top: 7, left: 2, bottom: 7, right: 2 })');
    await view(page, "view.setCellInput(7, 2, 'first')");
    // setCellInput on another cell than the selected one.
    await view(page, "view.setCellInput(0, 0, '100')");
    expect((await cell(page, 'A1')).value).toBe(100);
    await view(page, 'view.setActiveSheet(1)');
    await view(page, 'view.select({ top: 3, left: 3, bottom: 3, right: 3 })');

    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await view(page, 'view.activeSheet')).toBe(0);
    expect((await cell(page, 'A1')).value).toBe(1);
    expect(await selection(page)).toEqual({ active: 'C8', range: 'C8' });
    await expect(page.locator('.bym-tabs button[aria-selected="true"]')).toHaveText('Data');
    expect(await view(page, 'view.undo()')).toBe(true);
    expect((await cell(page, 'C8')).value).toBeUndefined();
    expect(await view(page, 'view.undo()')).toBe(false);
    expect(await view(page, 'view.redo()')).toBe(true);
    expect(await view(page, 'view.redo()')).toBe(true);
    expect(await view(page, 'view.redo()')).toBe(false);
    expect([(await cell(page, 'C8')).value, (await cell(page, 'A1')).value]).toEqual(['first', 100]);
    expect((await events(page, 'change')).map((event) => event.sheets)).toEqual([[0], [0], [0], [0], [0], [0]]);
  });

  test('clearSelection() and a new change drops what could be redone', async ({ page }) => {
    await mount(page, await editWorkbook());
    await select(page, 'A1:B1');
    await view(page, 'view.clearSelection()');
    expect((await cell(page, 'B1')).value).toBeUndefined();
    await view(page, 'view.undo()');
    expect(await view(page, 'view.history.canRedo')).toBe(true);
    await view(page, "view.setCellInput(5, 5, 'new')");
    expect(await view(page, 'view.history.canRedo')).toBe(false);
    expect(await view(page, 'view.redo()')).toBe(false);
    expect((await cell(page, 'B1')).value).toBe(2);
  });
});

test.describe('clipboard', () => {
  test('copy() and paste() move cells with their formulas; outside text is typed in', async ({ page }) => {
    await mount(page, await editWorkbook());
    await select(page, 'A1:C1');
    const copied = await view<{ text: string; html: string }>(page, '(({ text, html }) => ({ text, html }))(view.copy())');
    expect(copied.text).toBe('1\t2\t3');
    // The table carries a mark that names this copy.
    expect(copied.html).toMatch(/^<table data-bym-copy="[a-z0-9]+"><tr><td>1<\/td><td>2<\/td><td>3<\/td><\/tr><\/table>$/);
    expect(await events(page, 'change')).toEqual([]);

    await select(page, 'B8');
    await page.evaluate(({ text, html }) => (window as any).__view.paste(text, html), copied);
    expect([(await cell(page, 'B8')).value, (await cell(page, 'C8')).value]).toEqual([1, 2]);
    // The formula moved one column right and seven rows down with its cell.
    expect((await cell(page, 'D8')).formula).toBe('B8+C8');
    expect(await selection(page)).toEqual({ active: 'B8', range: 'B8:D8' });
    expect(await events(page, 'change')).toHaveLength(1);

    // Text from elsewhere: tabs and line breaks make cells, each read as typed.
    await select(page, 'G2');
    await page.evaluate(() => (window as any).__view.paste('name\tshare\nfirst\t25%\r\n"two\nlines"\t=G2'));
    expect(await selection(page)).toEqual({ active: 'G2', range: 'G2:H4' });
    expect([(await cell(page, 'G2')).value, (await cell(page, 'H2')).value, (await cell(page, 'G3')).value]).toEqual(['name', 'share', 'first']);
    expect(await cell(page, 'H3')).toMatchObject({ kind: 'number', value: 0.25, shown: '25%' });
    expect((await cell(page, 'G4')).value).toBe('two\nlines');
    expect((await cell(page, 'H4')).formula).toBe('G2');
    // One paste is one undo step.
    await view(page, 'view.undo()');
    expect([(await cell(page, 'G2')).value, (await cell(page, 'H4')).formula]).toEqual([undefined, undefined]);
    expect((await cell(page, 'D8')).formula).toBe('B8+C8');
  });

  test('copy, cut and paste events on the input', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'A1:C2');
    const copy = await clipboardEvent(page, 'copy');
    expect(copy.prevented).toBe(true);
    expect(copy.text).toBe('1\t2\t3\nhello\t\t');
    expect(copy.html).toContain('><tr><td>1</td><td>2</td><td>3</td></tr><tr><td>hello</td>');
    expect((await cell(page, 'A1')).value).toBe(1);

    await select(page, 'B8');
    const paste = await clipboardEvent(page, 'paste', copy.text, copy.html);
    expect(paste.prevented).toBe(true);
    expect(await selection(page)).toEqual({ active: 'B8', range: 'B8:D9' });
    expect([(await cell(page, 'B8')).value, (await cell(page, 'B9')).value, (await cell(page, 'D8')).formula]).toEqual([1, 'hello', 'B8+C8']);

    await select(page, 'B8:D9');
    const cut = await clipboardEvent(page, 'cut');
    expect(cut.prevented).toBe(true);
    // The pasted formula was calculated where it landed: B8 + C8 is 1 + 2.
    expect(cut.text).toBe('1\t2\t3\nhello\t\t');
    expect([(await cell(page, 'B8')).value, (await cell(page, 'B9')).value, (await cell(page, 'D8')).formula]).toEqual([undefined, undefined, undefined]);
    // Cutting is one step to undo.
    await page.keyboard.press('Control+z');
    expect([(await cell(page, 'B8')).value, (await cell(page, 'D8')).formula]).toEqual([1, 'B8+C8']);

    // Plain text from another program.
    await select(page, 'F1');
    await clipboardEvent(page, 'paste', '7\t8');
    expect([(await cell(page, 'F1')).value, (await cell(page, 'G1')).value]).toEqual([7, 8]);
    await expect(live(page)).toHaveText('F1 7, F1:G1 selected');
  });

  test('while a cell is edited the clipboard belongs to the editor text', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'A2');
    await page.keyboard.press('F2');
    for (const type of ['copy', 'cut', 'paste'] as const) {
      const result = await clipboardEvent(page, type, 'pasted');
      expect(result.prevented, type).toBe(false);
    }
    expect(await editorState(page)).toMatchObject({ editing: true, value: 'hello' });
    await page.keyboard.press('Escape');
    expect((await cell(page, 'A2')).value).toBe('hello');
  });

  test('the idle input holds the cell text selected, so that copy and cut fire everywhere', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    const idle = () =>
      page.evaluate(() => {
        const element = document.querySelector('.bym-input') as HTMLTextAreaElement;
        return { value: element.value, selected: element.value.slice(element.selectionStart, element.selectionEnd) };
      });
    await select(page, 'A2');
    expect(await idle()).toEqual({ value: 'hello', selected: 'hello' });
    await page.keyboard.press('ArrowUp');
    expect(await idle()).toEqual({ value: '1', selected: '1' });
    await select(page, 'F9');
    expect(await idle()).toEqual({ value: ' ', selected: ' ' });
  });
});

test.describe('rows and columns', () => {
  test('insertRows and deleteRows move cells, formulas, merged cells and row heights', async ({ page }) => {
    await mount(page, await editWorkbook());
    await view(page, 'view.insertRows(0, 2)');
    expect(await rawRange(page)).toEqual({ top: 0, bottom: 1, left: 0, right: MAX_COLS - 1 });
    expect((await cell(page, 'A3')).value).toBe(1);
    expect((await cell(page, 'C3')).formula).toBe('A3+B3');
    expect((await cell(page, 'A1')).value).toBeUndefined();
    expect((await cell(page, 'A1', 1)).formula).toBe('Data!A5');
    expect(await view(page, 'view.workbook.sheets[0].merges')).toEqual([{ top: 6, left: 3, bottom: 7, right: 4 }]);
    expect((await events(page, 'change')).map((event) => event.sheets)).toEqual([[0, 1]]);

    // The high row is now row 14: one row further down is 40 pixels lower, not 20.
    const height = await page.evaluate(() => {
      const api = (window as any).BymOffice;
      const view = (window as any).__view;
      const sheet = view.workbook.sheets[0];
      const layout = api.createLayout(api.createSheetMetrics(sheet), sheet.view, view.getViewState());
      return [11, 13].map((row) => api.cellRect(layout, row, 0).height);
    });
    expect(height).toEqual([20, 40]);

    await view(page, 'view.deleteRows(0, 1)');
    expect((await cell(page, 'C2')).formula).toBe('A2+B2');
    expect((await cell(page, 'A1', 1)).formula).toBe('Data!A4');
    // Deleting leaves the selection where it was.
    expect(await rawRange(page)).toEqual({ top: 0, bottom: 1, left: 0, right: MAX_COLS - 1 });

    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect((await cell(page, 'C1')).formula).toBe('A1+B1');
    expect((await cell(page, 'A1', 1)).formula).toBe('Data!A3');
    expect(await view(page, 'view.workbook.sheets[0].merges')).toEqual([{ top: 4, left: 3, bottom: 5, right: 4 }]);
    expect(await selection(page)).toEqual({ active: 'A1', range: 'A1' });
  });

  test('after an insert a click lands on the cell that is now under the pointer', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    // Row 12 is 40 pixels high: 30 pixels below the top of row 12 is still row 12.
    const y = box.y + HEADER_HEIGHT + 11 * ROW_HEIGHT + 30;
    await page.mouse.click(pointIn(box, 0, 1).x, y);
    expect(await selection(page)).toEqual({ active: 'B12', range: 'B12' });

    await view(page, 'view.insertRows(2, 3)');
    // Rows 12 to 14 are ordinary now and the same point is in row 13; the high row is row 15.
    await page.mouse.click(pointIn(box, 0, 1).x, y);
    expect(await selection(page)).toEqual({ active: 'B13', range: 'B13' });
    await page.mouse.click(pointIn(box, 0, 1).x, box.y + HEADER_HEIGHT + 14 * ROW_HEIGHT + 30);
    expect(await selection(page)).toEqual({ active: 'B15', range: 'B15' });
    expect((await cell(page, 'A15')).value).toBe(12);

    // The merged range moved with its rows: clicking where it is now selects it whole.
    const merged = pointIn(box, 8, 4);
    await page.mouse.click(merged.x, merged.y);
    expect(await selection(page)).toEqual({ active: 'D8', range: 'D8:E9' });

    await view(page, 'view.undo()');
    await page.mouse.click(pointIn(box, 0, 1).x, y);
    expect(await selection(page)).toEqual({ active: 'B12', range: 'B12' });
  });

  test('insertColumns and deleteColumns', async ({ page }) => {
    await mount(page, await editWorkbook());
    await view(page, 'view.insertColumns(1, 2)');
    expect(await rawRange(page)).toEqual({ top: 0, bottom: MAX_ROWS - 1, left: 1, right: 2 });
    expect([(await cell(page, 'A1')).value, (await cell(page, 'B1')).value, (await cell(page, 'D1')).value]).toEqual([1, undefined, 2]);
    expect((await cell(page, 'E1')).formula).toBe('A1+D1');
    expect(await view(page, 'view.workbook.sheets[0].merges')).toEqual([{ top: 4, left: 5, bottom: 5, right: 6 }]);
    await view(page, 'view.deleteColumns(0, 3)');
    expect((await cell(page, 'A1')).value).toBe(2);
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect((await cell(page, 'C1')).formula).toBe('A1+B1');
    expect(await view(page, 'view.history.canUndo')).toBe(false);
  });

  test('the header menu inserts and deletes with the mouse', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    const menu = page.locator('.bym-view .bym-menu');
    const items = menu.locator('button');
    await expect(menu).toHaveCount(0);

    // Row 3.
    await page.mouse.click(box.x + HEADER_WIDTH / 2, pointIn(box, 2, 0).y, { button: 'right' });
    await expect(menu).toBeVisible();
    await expect(menu).toHaveAttribute('role', 'menu');
    await expect(items).toHaveText(['Insert row above', 'Insert row below', 'Delete row']);
    await expect(menu.locator('[role="menuitem"]')).toHaveCount(3);
    await expect(items.nth(0)).toBeFocused();
    expect(await rawRange(page)).toEqual({ top: 2, bottom: 2, left: 0, right: MAX_COLS - 1 });
    await items.nth(0).click();
    await expect(menu).toHaveCount(0);
    await expect(input(page)).toBeFocused();
    expect([(await cell(page, 'A3')).value, (await cell(page, 'A4')).value]).toEqual([undefined, 10]);
    expect(await rawRange(page)).toEqual({ top: 2, bottom: 2, left: 0, right: MAX_COLS - 1 });

    // Three rows selected: the menu speaks of three, and "below" goes after the last of them.
    await page.evaluate((cols) => (window as any).__view.select({ top: 0, bottom: 2, left: 0, right: cols - 1 }), MAX_COLS);
    await page.mouse.click(box.x + HEADER_WIDTH / 2, pointIn(box, 1, 0).y, { button: 'right' });
    await expect(items).toHaveText(['Insert 3 rows above', 'Insert 3 rows below', 'Delete 3 rows']);
    await items.nth(1).click();
    expect(await rawRange(page)).toEqual({ top: 3, bottom: 5, left: 0, right: MAX_COLS - 1 });
    expect([(await cell(page, 'A1')).value, (await cell(page, 'A7')).value]).toEqual([1, 10]);

    // Column B.
    await page.mouse.click(pointIn(box, 0, 1).x, box.y + HEADER_HEIGHT / 2, { button: 'right' });
    await expect(items).toHaveText(['Insert column left', 'Insert column right', 'Delete column']);
    await items.nth(2).click();
    expect([(await cell(page, 'A1')).value, (await cell(page, 'B1')).formula]).toEqual([1, 'A1+#REF!']);
    expect(await rawRange(page)).toEqual({ top: 0, bottom: MAX_ROWS - 1, left: 1, right: 1 });

    // A press elsewhere, a scroll and Escape each close the menu without doing anything.
    const changes = (await events(page, 'change')).length;
    await page.mouse.click(box.x + HEADER_WIDTH / 2, pointIn(box, 4, 0).y, { button: 'right' });
    await expect(menu).toBeVisible();
    const elsewhere = pointIn(box, 9, 5);
    await page.mouse.click(elsewhere.x, elsewhere.y);
    await expect(menu).toHaveCount(0);
    expect(await selection(page)).toEqual({ active: 'F10', range: 'F10' });

    await page.mouse.click(box.x + HEADER_WIDTH / 2, pointIn(box, 4, 0).y, { button: 'right' });
    await expect(menu).toBeVisible();
    await page.evaluate(() => {
      document.querySelector('.bym-scroller')!.scrollTop = 60;
    });
    await expect(menu).toHaveCount(0);

    // A right click on the corner is left to the browser.
    await page.evaluate(() => {
      document.querySelector('.bym-scroller')!.scrollTop = 0;
    });
    const prevented = await page.evaluate(
      ([x, y]) => {
        const event = new MouseEvent('contextmenu', { clientX: x, clientY: y, bubbles: true, cancelable: true, button: 2 });
        document.querySelector('.bym-canvas')!.dispatchEvent(event);
        return event.defaultPrevented;
      },
      [box.x + 10, box.y + 10],
    );
    expect(prevented).toBe(false);
    await expect(menu).toHaveCount(0);
    expect(await events(page, 'change')).toHaveLength(changes);
  });

  test('the header menu works with the keyboard', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    const menu = page.locator('.bym-view .bym-menu');
    const items = menu.locator('button');
    await page.mouse.click(box.x + HEADER_WIDTH / 2, pointIn(box, 0, 0).y, { button: 'right' });
    await expect(items.nth(0)).toBeFocused();
    await page.keyboard.press('ArrowDown');
    await expect(items.nth(1)).toBeFocused();
    await page.keyboard.press('ArrowDown');
    await expect(items.nth(2)).toBeFocused();
    await page.keyboard.press('ArrowDown');
    await expect(items.nth(0)).toBeFocused();
    await page.keyboard.press('ArrowUp');
    await expect(items.nth(2)).toBeFocused();
    // The arrows moved in the menu, not in the sheet.
    expect(await rawRange(page)).toEqual({ top: 0, bottom: 0, left: 0, right: MAX_COLS - 1 });

    await page.keyboard.press('Escape');
    await expect(menu).toHaveCount(0);
    await expect(input(page)).toBeFocused();
    expect(await events(page, 'change')).toEqual([]);

    await page.mouse.click(box.x + HEADER_WIDTH / 2, pointIn(box, 0, 0).y, { button: 'right' });
    await page.keyboard.press('End');
    await expect(items.nth(2)).toBeFocused();
    await page.keyboard.press('Enter');
    await expect(menu).toHaveCount(0);
    await expect(input(page)).toBeFocused();
    // Row 1 is gone: what was A2 is A1.
    expect((await cell(page, 'A1')).value).toBe('hello');
    // And the keyboard is back in the grid.
    await page.keyboard.press('Control+z');
    expect((await cell(page, 'A1')).value).toBe(1);
  });

  test('Ctrl+Shift+plus and Ctrl+minus on whole rows and columns', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await page.evaluate((cols) => (window as any).__view.select({ top: 1, bottom: 2, left: 0, right: cols - 1 }), MAX_COLS);
    await page.keyboard.press('Control+Shift+Equal');
    expect([(await cell(page, 'A2')).value, (await cell(page, 'A4')).value, (await cell(page, 'A5')).value]).toEqual([undefined, 'hello', 10]);
    expect(await rawRange(page)).toEqual({ top: 1, bottom: 2, left: 0, right: MAX_COLS - 1 });
    await page.keyboard.press('Control+Minus');
    expect([(await cell(page, 'A2')).value, (await cell(page, 'A3')).value]).toEqual(['hello', 10]);

    await page.evaluate((rows) => (window as any).__view.select({ top: 0, bottom: rows - 1, left: 0, right: 0 }), MAX_ROWS);
    await page.keyboard.press('Control+Shift+Equal');
    expect([(await cell(page, 'A1')).value, (await cell(page, 'B1')).value, (await cell(page, 'D1')).formula]).toEqual([undefined, 1, 'B1+C1']);
    await page.keyboard.press('Control+Minus');
    expect((await cell(page, 'C1')).formula).toBe('A1+B1');
    expect(await events(page, 'change')).toHaveLength(4);

    // On a cell selection the keys are not the view's: nothing changes and the browser keeps them.
    await select(page, 'B2');
    const prevented = await page.evaluate(() => {
      const element = document.querySelector('.bym-input')!;
      return ['+', '-'].map((key) => {
        const event = new KeyboardEvent('keydown', { key, ctrlKey: true, bubbles: true, cancelable: true });
        element.dispatchEvent(event);
        return event.defaultPrevented;
      });
    });
    expect(prevented).toEqual([false, false]);
    expect(await events(page, 'change')).toHaveLength(4);
  });

  test('an insert that would push cells off the sheet is refused and nothing breaks', async ({ page, hasTouch }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await page.evaluate((rows) => (window as any).__view.setCellInput(rows - 1, 0, 'last'), MAX_ROWS);
    const before = await events(page, 'change');

    // Called from code, the error is the caller's.
    const thrown = await page.evaluate(() => {
      try {
        (window as any).__view.insertRows(0, 1);
        return 'nothing';
      } catch (error) {
        return (error as Error).name;
      }
    });
    expect(thrown).toBe('RangeError');
    const invalid = await page.evaluate(() => {
      try {
        (window as any).__view.deleteColumns(-1, 0);
        return 'nothing';
      } catch (error) {
        return (error as Error).name;
      }
    });
    expect(invalid).toBe('RangeError');

    // From the keyboard it is announced.
    await page.evaluate((cols) => (window as any).__view.select({ top: 0, bottom: 0, left: 0, right: cols - 1 }), MAX_COLS);
    await page.keyboard.press('Control+Shift+Equal');
    await expect(live(page)).toHaveText(/Cannot insert/);
    expect(await events(page, 'change')).toEqual(before);
    expect([(await cell(page, 'A1')).value, (await cell(page, 'C1')).formula]).toEqual([1, 'A1+B1']);
    expect(await view(page, 'view.workbook.sheets[0].rowCount')).toBe(MAX_ROWS);

    // The view goes on working.
    await select(page, 'B8');
    await page.keyboard.type('ok');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'B8')).value).toBe('ok');
    if (!hasTouch) {
      const box = await canvasBox(page);
      const p = pointIn(box, 4, 2);
      await page.mouse.click(p.x, p.y);
      expect(await selection(page)).toEqual({ active: 'C5', range: 'C5' });
    }
    // Only the last change is undone; the refused insert left no step behind.
    await view(page, 'view.undo()');
    expect((await cell(page, 'B8')).value).toBeUndefined();
    await view(page, 'view.undo()');
    expect(await view(page, 'view.history.canUndo')).toBe(false);
  });

  test('a long press on a header opens the menu', async ({ page, hasTouch }) => {
    test.skip(!hasTouch, TOUCH_ONLY);
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    const x = box.x + HEADER_WIDTH / 2;
    const y = pointIn(box, 2, 0).y;
    const fire = (type: string, dy = 0) =>
      page.evaluate(
        ([type, x, y]) => {
          document
            .querySelector('.bym-canvas')!
            .dispatchEvent(new PointerEvent(type as string, { pointerId: 21, pointerType: 'touch', isPrimary: true, clientX: x as number, clientY: y as number, bubbles: true, cancelable: true }));
        },
        [type, x, y + dy] as [string, number, number],
      );
    const menu = page.locator('.bym-view .bym-menu');

    // A finger that moves away is a scroll, not a long press.
    await fire('pointerdown');
    await fire('pointermove', 40);
    await fire('pointercancel', 40);
    await fire('pointerdown');
    await expect(menu).toBeVisible();
    await expect(menu.locator('button')).toHaveText(['Insert row above', 'Insert row below', 'Delete row']);
    await fire('pointerup');
    await expect(menu).toBeVisible();
    expect(await rawRange(page)).toEqual({ top: 2, bottom: 2, left: 0, right: MAX_COLS - 1 });

    await menu.locator('button').nth(2).tap();
    await expect(menu).toHaveCount(0);
    expect((await cell(page, 'A3')).value).toBeUndefined();
    expect(await events(page, 'change')).toHaveLength(1);
  });
});

test.describe('read-only', () => {
  test('nothing edits; copying still works', async ({ page, hasTouch }) => {
    await mount(page, await editWorkbook(), { readOnly: true });
    await focusGrid(page);
    await expect(input(page)).toHaveAttribute('readonly', '');
    await select(page, 'A1:C1');

    await page.keyboard.type('x');
    await page.keyboard.press('F2');
    expect(await view(page, 'view.isEditing')).toBe(false);
    await page.keyboard.press('Delete');
    await page.keyboard.press('Control+z');
    const result = await page.evaluate((cols) => {
      const view = (window as any).__view;
      view.startEditing('typed');
      const editing = view.isEditing;
      view.setCellInput(0, 0, '99');
      view.clearSelection();
      view.paste('5\t6');
      view.insertRows(0, 1);
      view.deleteRows(0, 1);
      view.insertColumns(0, 1);
      view.deleteColumns(0, 1);
      const cut = view.cut();
      const copy = view.copy();
      view.select({ top: 0, bottom: 0, left: 0, right: cols - 1 });
      return { editing, cut: cut.text, copy: copy.text, undo: view.undo(), redo: view.redo(), canUndo: view.history.canUndo };
    }, MAX_COLS);
    expect(result).toEqual({ editing: false, cut: '1\t2\t3', copy: '1\t2\t3', undo: false, redo: false, canUndo: false });
    await page.keyboard.press('Control+Shift+Equal');
    await page.keyboard.press('Control+Minus');

    await select(page, 'A1:C1');
    const copied = await clipboardEvent(page, 'copy');
    expect(copied).toMatchObject({ prevented: true, text: '1\t2\t3' });
    const cut = await clipboardEvent(page, 'cut');
    expect(cut.text).toBe('1\t2\t3');
    await clipboardEvent(page, 'paste', 'zzz');

    expect([(await cell(page, 'A1')).value, (await cell(page, 'B1')).value, (await cell(page, 'C1')).formula, (await cell(page, 'A2')).value]).toEqual([1, 2, 'A1+B1', 'hello']);
    expect(await events(page, 'change')).toEqual([]);

    if (!hasTouch) {
      const box = await canvasBox(page);
      const a2 = pointIn(box, 1, 0);
      await page.mouse.dblclick(a2.x, a2.y);
      expect(await view(page, 'view.isEditing')).toBe(false);
      await page.mouse.click(box.x + HEADER_WIDTH / 2, a2.y, { button: 'right' });
      await expect(page.locator('.bym-menu')).toHaveCount(0);
    }
    // Moving around still works.
    await select(page, 'A1');
    await focusGrid(page);
    await page.keyboard.press('ArrowDown');
    expect(await selection(page)).toEqual({ active: 'A2', range: 'A2' });
  });
});

test.describe('input methods', () => {
  test('a composition starts the editor and its confirming Enter does not end it', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'A2');
    const result = await page.evaluate(() => {
      const view = (window as any).__view;
      const element = document.querySelector('.bym-input') as HTMLTextAreaElement;
      const states: boolean[] = [];
      const key = (init: KeyboardEventInit & { keyCode?: number }) => {
        const event = new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true, ...init });
        if (init.keyCode !== undefined && event.keyCode !== init.keyCode) Object.defineProperty(event, 'keyCode', { value: init.keyCode });
        element.dispatchEvent(event);
        return event.defaultPrevented;
      };
      element.dispatchEvent(new CompositionEvent('compositionstart', { bubbles: true, data: '' }));
      states.push(view.isEditing);
      // The input method replaces the selected idle text with what is being composed.
      element.value = 'に';
      element.dispatchEvent(new CompositionEvent('compositionupdate', { bubbles: true, data: 'に' }));
      element.dispatchEvent(new InputEvent('input', { bubbles: true, isComposing: true, data: 'に', inputType: 'insertCompositionText' }));
      element.value = '日本';
      element.dispatchEvent(new InputEvent('input', { bubbles: true, isComposing: true, data: '日本', inputType: 'insertCompositionText' }));
      // Enter picks the candidate: reported as composing by some browsers, as key code 229 by others.
      const prevented = [key({ isComposing: true }), key({ keyCode: 229 })];
      states.push(view.isEditing);
      element.dispatchEvent(new CompositionEvent('compositionend', { bubbles: true, data: '日本' }));
      states.push(view.isEditing);
      return { states, prevented, value: element.value, opacity: getComputedStyle(element).opacity };
    });
    expect(result).toEqual({ states: [true, true, true], prevented: [false, false], value: '日本', opacity: '1' });
    expect((await cell(page, 'A2')).value).toBe('hello');

    await page.keyboard.press('Enter');
    expect((await cell(page, 'A2')).value).toBe('日本');
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect(await selection(page)).toEqual({ active: 'A3', range: 'A3' });
  });

  test('a key that went to an input method does not move the selection', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    const prevented = await page.evaluate(() => {
      const element = document.querySelector('.bym-input')!;
      const event = new KeyboardEvent('keydown', { key: 'ArrowDown', isComposing: true, bubbles: true, cancelable: true });
      element.dispatchEvent(event);
      return event.defaultPrevented;
    });
    expect(prevented).toBe(false);
    expect(await selection(page)).toEqual({ active: 'A1', range: 'A1' });
  });
});

test.describe('editing while the view changes', () => {
  test('the editor moves with its cell and waits out of sight when the cell is scrolled away', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.keyboard.type('keep');
    const box = await canvasBox(page);
    const scrollTo = async (top: number) => {
      await page.evaluate((top) => {
        document.querySelector('.bym-scroller')!.scrollTop = top;
        (window as any).__view.render();
      }, top);
    };
    await scrollTo(60);
    let editor = await editorState(page);
    expect(editor).toMatchObject({ editing: true, value: 'keep', opacity: '1' });
    expect(Math.round(editor.box.y - box.y)).toBe(HEADER_HEIGHT + 7 * ROW_HEIGHT - 60 - 1);

    await scrollTo(600);
    editor = await editorState(page);
    expect(editor).toMatchObject({ editing: true, value: 'keep', opacity: '0' });
    // Parked inside the view, so the browser has no reason to scroll anything.
    expect(editor.box.x).toBeGreaterThanOrEqual(box.x);
    expect(editor.box.y).toBeGreaterThanOrEqual(box.y);
    expect(editor.box.y).toBeLessThan(box.y + box.height);
    await expect(input(page)).toBeFocused();

    await scrollTo(0);
    editor = await editorState(page);
    expect(editor).toMatchObject({ editing: true, value: 'keep', opacity: '1' });
    expect(Math.round(editor.box.y - box.y)).toBe(HEADER_HEIGHT + 7 * ROW_HEIGHT - 1);
    await page.keyboard.press('Enter');
    expect((await cell(page, 'B8')).value).toBe('keep');
  });

  test('typing in a cell that is out of view brings it back', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.evaluate(() => {
      document.querySelector('.bym-scroller')!.scrollTop = 900;
    });
    await page.keyboard.type('z');
    const editor = await editorState(page);
    expect(editor).toMatchObject({ editing: true, opacity: '1' });
    const box = await canvasBox(page);
    expect(editor.box.y).toBeGreaterThanOrEqual(box.y + HEADER_HEIGHT - 1);
    expect(editor.box.y + editor.box.height).toBeLessThanOrEqual(box.y + box.height + 1);
    await page.keyboard.press('Escape');
  });

  test('changing sheet or leaving the input writes the edit', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.keyboard.type('one');
    await view(page, 'view.setActiveSheet(1)');
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'B8', 0)).value).toBe('one');
    expect((await cell(page, 'B8', 1)).value).toBeUndefined();
    expect((await events(page, 'change')).map((event) => event.sheets)).toEqual([[0]]);

    await focusGrid(page);
    await page.keyboard.type('two');
    await page.locator('.bym-tabs button', { hasText: 'Data' }).click();
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'A1', 1)).value).toBe('two');
    expect(await view(page, 'view.activeSheet')).toBe(0);

    await focusGrid(page);
    await select(page, 'C8');
    await page.keyboard.type('three');
    await page.locator('#after').focus();
    await expect.poll(() => view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'C8')).value).toBe('three');
  });

  test('commitEditing, cancelEditing and startEditing from code', async ({ page }) => {
    await mount(page, await editWorkbook());
    await select(page, 'A2');
    expect(await view(page, 'view.commitEditing()')).toBe(false);
    await view(page, 'view.startEditing()');
    expect(await editorState(page)).toMatchObject({ editing: true, value: 'hello', opacity: '1' });
    await expect(input(page)).toBeFocused();
    await view(page, 'view.cancelEditing()');
    expect(await view(page, 'view.isEditing')).toBe(false);

    await view(page, "view.startEditing('=B1')");
    expect((await editorState(page)).value).toBe('=B1');
    expect(await view(page, 'view.commitEditing()')).toBe(true);
    expect((await cell(page, 'A2')).formula).toBe('B1');
    // commitEditing leaves the selection where it is.
    expect(await selection(page)).toEqual({ active: 'A2', range: 'A2' });
    expect(await events(page, 'change')).toHaveLength(1);
  });

  test('destroy during an edit discards it quietly', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await page.keyboard.type('lost');
    const result = await page.evaluate(() => {
      const view = (window as any).__view;
      const host = document.getElementById('host')!;
      view.destroy();
      return { children: host.children.length, editing: view.isEditing, inputs: document.querySelectorAll('.bym-input, .bym-menu').length };
    });
    expect(result).toEqual({ children: 0, editing: false, inputs: 0 });
    expect((await cell(page, 'A1')).value).toBe(1);
    expect(await events(page, 'change')).toEqual([]);
    // The methods are harmless afterwards.
    await page.evaluate(() => {
      const view = (window as any).__view;
      view.startEditing('x');
      view.setCellInput(0, 0, '5');
      view.paste('5');
      view.insertRows(0, 1);
      view.undo();
    });
    expect((await cell(page, 'A1')).value).toBe(1);
  });

  test('destroy with the menu open removes it and its listeners', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    await page.mouse.click(box.x + HEADER_WIDTH / 2, pointIn(box, 2, 0).y, { button: 'right' });
    await expect(page.locator('.bym-menu')).toBeVisible();
    await page.evaluate(() => (window as any).__view.destroy());
    await expect(page.locator('.bym-menu')).toHaveCount(0);
    await page.mouse.click(10, 10);
    await page.keyboard.press('Escape');
    expect((await cell(page, 'A3')).value).toBe(10);
  });
});

test.describe('touch', () => {
  test.beforeEach(({ hasTouch }) => {
    test.skip(!hasTouch, TOUCH_ONLY);
  });

  test('a tap keeps the keyboard closed; a double tap edits and asks for it', async ({ page }) => {
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    const a2 = pointIn(box, 1, 0);
    await page.touchscreen.tap(a2.x, a2.y);
    await expect.poll(() => selection(page)).toEqual({ active: 'A2', range: 'A2' });
    await expect(input(page)).toBeFocused();
    expect(await editorState(page)).toMatchObject({ editing: false, mode: 'none' });

    await page.touchscreen.tap(a2.x, a2.y);
    await expect.poll(() => view(page, 'view.isEditing')).toBe(true);
    expect(await editorState(page)).toMatchObject({ value: 'hello', mode: 'text', opacity: '1' });
    await expect(input(page)).toBeFocused();
    await page.keyboard.type('!');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A2')).value).toBe('hello!');
    expect(await editorState(page)).toMatchObject({ editing: false, mode: 'none' });
    await expect(input(page)).toBeFocused();

    // Two taps on different cells are two taps.
    const c5 = pointIn(box, 4, 2);
    await page.touchscreen.tap(a2.x, a2.y);
    await page.touchscreen.tap(c5.x, c5.y);
    await expect.poll(() => selection(page)).toEqual({ active: 'C5', range: 'C5' });
    expect(await view(page, 'view.isEditing')).toBe(false);
  });

  test('a tap on another cell writes the edit', async ({ page }) => {
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    await select(page, 'B8');
    await view(page, "view.startEditing('tapped')");
    const c5 = pointIn(box, 4, 2);
    await page.touchscreen.tap(c5.x, c5.y);
    await expect.poll(() => view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'B8')).value).toBe('tapped');
    await expect.poll(() => selection(page)).toEqual({ active: 'C5', range: 'C5' });
  });
});

test.describe('large sheets', () => {
  test('editing a cell and inserting a row in 100,000 rows of formulas stays quick', async ({ page }) => {
    test.setTimeout(120_000);
    await mount(page, await bigWorkbook());
    await focusGrid(page);
    await select(page, 'A50000');
    await page.keyboard.type('7');
    const typed = await page.evaluate(() => {
      const element = document.querySelector('.bym-input')!;
      const started = performance.now();
      element.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true }));
      return performance.now() - started;
    });
    expect((await cell(page, 'A50000')).value).toBe(7);
    // The first change also reads all 100,000 formulas into the dependency graph; later ones do not.
    expect(typed, 'writing the first cell, in ms').toBeLessThan(1500);

    const timings = await page.evaluate(() => {
      const view = (window as any).__view;
      const time = (run: () => void) => {
        const started = performance.now();
        run();
        view.render();
        return performance.now() - started;
      };
      return {
        set: time(() => view.setCellInput(10, 0, '5')),
        insert: time(() => view.insertRows(10, 1)),
        undo: time(() => view.undo()),
        redo: time(() => view.redo()),
      };
    });
    expect(timings.set, 'setCellInput, in ms').toBeLessThan(200);
    expect(timings.insert, 'insertRows, in ms').toBeLessThan(3000);
    expect(timings.undo, 'undo of the insert, in ms').toBeLessThan(3000);
    expect(timings.redo, 'redo of the insert, in ms').toBeLessThan(3000);
    // Row 11 is new; the formula that was in B11 is in B12 and points at A12.
    expect((await cell(page, 'A11')).value).toBeUndefined();
    expect((await cell(page, 'B12')).formula).toBe('A12*2');
    expect(await view(page, 'view.workbook.sheets[0].rowCount')).toBe(BIG_ROWS + 1);
  });
});

// ---------------------------------------------------------------------------
// Second round: defects found in review, each with the test that shows it.

/**
 * A1=1, A2=2, C3=A1+A2 (shown as 3), A5 text with a carriage return and line
 * feed in it, F2:F4 a shared formula (A2*2 and its dependants), D8:E9 merged.
 */
const reviewWorkbook = once(() =>
  buildXlsx({
    sheets: [
      {
        name: 'Review',
        xml: worksheetXml(
          '<sheetData>' +
            `<row r="1">${num('A1', 1)}</row>` +
            `<row r="2">${num('A2', 2)}<c r="F2"><f t="shared" ref="F2:F4" si="0">A2*2</f><v>4</v></c></row>` +
            '<row r="3"><c r="C3"><f>A1+A2</f><v>3</v></c><c r="F3"><f t="shared" si="0"/><v>0</v></c></row>' +
            '<row r="4"><c r="F4"><f t="shared" si="0"/><v>0</v></c></row>' +
            '<row r="5"><c r="A5" t="inlineStr"><is><t>x&#13;&#10;y</t></is></c></row>' +
            `<row r="8">${num('D8', 8)}</row>` +
            '</sheetData><mergeCells count="1"><mergeCell ref="D8:E9"/></mergeCells>',
        ),
      },
      { name: 'Second', xml: worksheetXml('<sheetData/>') },
    ],
  }),
);

/** A key event sent straight to the input; returns whether the view took it. */
function sendKey(page: Page, init: { key: string; ctrlKey?: boolean; altKey?: boolean; metaKey?: boolean; shiftKey?: boolean }): Promise<boolean> {
  return page.evaluate((init) => {
    const event = new KeyboardEvent('keydown', { bubbles: true, cancelable: true, ...init });
    document.querySelector('.bym-input')!.dispatchEvent(event);
    return event.defaultPrevented;
  }, init);
}

/** A pointer event of a finger on the canvas, at page coordinates. */
function touchEvent(page: Page, type: string, x: number, y: number, id = 31): Promise<void> {
  return page.evaluate(
    ([type, x, y, id]) => {
      document
        .querySelector('.bym-canvas')!
        .dispatchEvent(new PointerEvent(type as string, { pointerId: id as number, pointerType: 'touch', isPrimary: true, clientX: x as number, clientY: y as number, bubbles: true, cancelable: true }));
    },
    [type, x, y, id] as [string, number, number, number],
  );
}

/** A right click (or long press) as the browser reports it: a contextmenu event at page coordinates. */
function contextMenuAt(page: Page, x: number, y: number): Promise<boolean> {
  return page.evaluate(
    ([x, y]) => {
      const event = new MouseEvent('contextmenu', { clientX: x, clientY: y, button: 2, bubbles: true, cancelable: true });
      document.querySelector('.bym-canvas')!.dispatchEvent(event);
      return event.defaultPrevented;
    },
    [x, y],
  );
}

const twoFrames = (page: Page) => page.evaluate(() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))));

test.describe('review: the editor', () => {
  test('looking at text with a carriage return and confirming it changes nothing', async ({ page }) => {
    await mount(page, await reviewWorkbook());
    await focusGrid(page);
    expect((await cell(page, 'A5')).value, 'the fixture keeps its carriage return').toBe('x\r\ny');
    await select(page, 'A5');
    await page.keyboard.press('F2');
    expect((await editorState(page)).value).toBe('x\ny');
    await page.keyboard.press('Enter');
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'A5')).value).toBe('x\r\ny');
    expect(await events(page, 'change')).toEqual([]);
    expect(await view(page, 'view.history.canUndo')).toBe(false);

    // The same when the focus leaves instead.
    await select(page, 'A5');
    await page.keyboard.press('F2');
    await page.locator('#after').focus();
    await expect.poll(() => view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'A5')).value).toBe('x\r\ny');
    expect(await events(page, 'change')).toEqual([]);

    // A real change is still written.
    await focusGrid(page);
    await select(page, 'A5');
    await page.keyboard.press('F2');
    await page.keyboard.type('z');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A5')).value).toBe('x\nyz');
  });

  test('typing replaces the whole idle text even after its selection was collapsed', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'A2');
    // End is not a key of the view; the browser moves the caret of the idle text with it.
    await page.keyboard.press('End');
    await page.keyboard.type('x');
    expect(await editorState(page)).toMatchObject({ editing: true, value: 'x' });
    await page.keyboard.press('Escape');
    await page.evaluate(() => {
      const element = document.querySelector('.bym-input') as HTMLTextAreaElement;
      element.setSelectionRange(2, 2);
    });
    await page.keyboard.type('yz');
    expect((await editorState(page)).value).toBe('yz');
    await page.keyboard.press('Escape');
  });

  test('deleting the idle text never opens the editor; Backspace and Delete with a modifier clear the selection', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    for (const modifier of ['Control', 'Alt', 'Meta']) {
      await select(page, 'A2');
      await page.keyboard.press(`${modifier}+Backspace`);
      expect(await view(page, 'view.isEditing'), modifier).toBe(false);
      expect((await cell(page, 'A2')).value, modifier).toBeUndefined();
      await page.keyboard.press('Enter');
      await view(page, 'view.undo()');
      expect((await cell(page, 'A2')).value, modifier).toBe('hello');
    }
    await select(page, 'A3');
    await page.keyboard.press('Control+Delete');
    expect((await cell(page, 'A3')).value).toBeUndefined();
    expect(await view(page, 'view.isEditing')).toBe(false);
    await view(page, 'view.undo()');

    // Whatever else makes the browser delete the idle text: the input event of a deletion starts nothing.
    await select(page, 'A2');
    const idle = await page.evaluate(() => {
      const element = document.querySelector('.bym-input') as HTMLTextAreaElement;
      const out: string[] = [];
      for (const inputType of ['deleteWordBackward', 'deleteContentForward', 'deleteByCut', 'historyUndo']) {
        element.value = '';
        element.dispatchEvent(new InputEvent('input', { bubbles: true, inputType }));
        out.push(`${(window as any).__view.isEditing}:${element.value}`);
      }
      return out;
    });
    expect(idle).toEqual(['false:hello', 'false:hello', 'false:hello', 'false:hello']);
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A2')).value).toBe('hello');
    expect((await cell(page, 'A3')).value).toBe(10);
  });

  test('Shift+Delete does not delete without copying', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'A2');
    // The key itself is left to the browser, which turns it into a cut event where it means "cut".
    expect(await sendKey(page, { key: 'Delete', shiftKey: true })).toBe(false);
    expect(await sendKey(page, { key: 'Backspace', shiftKey: true })).toBe(false);
    expect((await cell(page, 'A2')).value).toBe('hello');
    expect(await events(page, 'change')).toEqual([]);

    await page.keyboard.press('Shift+Delete');
    expect(await view(page, 'view.isEditing')).toBe(false);
    const changes = await events(page, 'change');
    // Either nothing happened, or the browser cut: then the cells are on the clipboard and one step undoes it.
    if (changes.length > 0) {
      expect(changes).toHaveLength(1);
      await view(page, 'view.undo()');
    }
    expect((await cell(page, 'A2')).value).toBe('hello');
  });

  test('an abandoned composition on an empty cell writes nothing', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'F9');
    const state = await page.evaluate(() => {
      const element = document.querySelector('.bym-input') as HTMLTextAreaElement;
      element.dispatchEvent(new CompositionEvent('compositionstart', { bubbles: true, data: '' }));
      element.dispatchEvent(new CompositionEvent('compositionend', { bubbles: true, data: '' }));
      return { editing: (window as any).__view.isEditing, value: element.value };
    });
    expect(state.editing).toBe(true);
    await page.keyboard.press('Enter');
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect(await cell(page, 'F9')).toEqual({ shown: '' });
    expect(await events(page, 'change')).toEqual([]);

    // And when the focus leaves.
    await select(page, 'F9');
    await page.evaluate(() => document.querySelector('.bym-input')!.dispatchEvent(new CompositionEvent('compositionstart', { bubbles: true, data: '' })));
    await page.locator('#after').focus();
    await expect.poll(() => view(page, 'view.isEditing')).toBe(false);
    expect(await cell(page, 'F9')).toEqual({ shown: '' });
    expect(await events(page, 'change')).toEqual([]);
  });

  test('a failed write keeps the editor open with its text and the message', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.keyboard.type('kept');
    // The operation layer refuses.
    await page.evaluate(() => {
      const history = (window as any).__view.history;
      (window as any).__apply = history.apply;
      history.apply = () => {
        throw new RangeError('The sheet refused the change');
      };
    });
    for (const key of ['Enter', 'Tab']) {
      await page.keyboard.press(key);
      expect(await editorState(page), key).toMatchObject({ editing: true, value: 'kept', opacity: '1' });
      expect(await selection(page), key).toEqual({ active: 'B8', range: 'B8' });
      // An error the view has no words for is announced in general terms, never in the engine's own.
      await expect(live(page)).toHaveText('The action could not be completed');
    }
    await expect(input(page)).toBeFocused();
    expect(await events(page, 'change')).toEqual([]);
    // From code the error is the caller's, and the editor is still open.
    const thrown = await page.evaluate(() => {
      try {
        (window as any).__view.commitEditing();
        return 'nothing';
      } catch (error) {
        return (error as Error).message;
      }
    });
    expect(thrown).toBe('The sheet refused the change');
    expect(await view(page, 'view.isEditing')).toBe(true);

    await page.evaluate(() => {
      (window as any).__view.history.apply = (window as any).__apply;
    });
    await page.keyboard.press('Enter');
    expect((await cell(page, 'B8')).value).toBe('kept');
    expect(await selection(page)).toEqual({ active: 'B9', range: 'B9' });
  });

  test('a failed write keeps a click from moving the selection', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.keyboard.type('kept');
    await page.evaluate(() => {
      (window as any).__view.history.apply = () => {
        throw new RangeError('The sheet refused the change');
      };
    });
    const box = await canvasBox(page);
    const p = pointIn(box, 2, 3);
    await page.mouse.click(p.x, p.y);
    expect(await editorState(page)).toMatchObject({ editing: true, value: 'kept' });
    expect(await selection(page)).toEqual({ active: 'B8', range: 'B8' });
    // An error the view has no words for is announced in general terms, never in the engine's own.
      await expect(live(page)).toHaveText('The action could not be completed');
    await expect(input(page)).toBeFocused();
  });

  test('undo and redo during an edit only abandon the edit', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await view(page, "view.setCellInput(0, 0, '100')");
    await select(page, 'B8');
    await page.keyboard.type('typed');
    expect(await view(page, 'view.undo()')).toBe(true);
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'B8')).value).toBeUndefined();
    // The step before the edit is untouched.
    expect((await cell(page, 'A1')).value).toBe(100);
    expect(await view(page, '[view.history.canUndo, view.history.canRedo]')).toEqual([true, false]);

    await view(page, 'view.undo()');
    expect((await cell(page, 'A1')).value).toBe(1);
    await page.keyboard.type('again');
    expect(await view(page, 'view.redo()')).toBe(true);
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'A1')).value).toBe(1);
    expect(await view(page, 'view.history.canRedo')).toBe(true);
    expect(await events(page, 'change')).toHaveLength(2);
  });

  test('clearSelection, cut, select and setReadOnly during an edit write it first', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.keyboard.type('one');
    await view(page, 'view.select({ top: 0, left: 0, bottom: 0, right: 0 })');
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'B8')).value).toBe('one');
    expect(await selection(page)).toEqual({ active: 'A1', range: 'A1' });

    await select(page, 'C8');
    await page.keyboard.type('two');
    await view(page, 'view.clearSelection()');
    expect(await view(page, 'view.isEditing')).toBe(false);
    // Written, then cleared: two steps.
    expect((await cell(page, 'C8')).value).toBeUndefined();
    await view(page, 'view.undo()');
    expect((await cell(page, 'C8')).value).toBe('two');

    await select(page, 'D8');
    await page.keyboard.type('three');
    expect(await view(page, 'view.cut().text')).toBe('three');
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'D8')).value).toBeUndefined();
    await view(page, 'view.undo()');
    expect((await cell(page, 'D8')).value).toBe('three');

    await select(page, 'E8');
    await page.keyboard.type('four');
    await view(page, 'view.setReadOnly(true)');
    expect(await view(page, '[view.isEditing, view.readOnly]')).toEqual([false, true]);
    expect((await cell(page, 'E8')).value).toBe('four');
  });

  test('setReadOnly switches editing off and on and keeps the history', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    expect(await view(page, 'view.readOnly')).toBe(false);
    await view(page, "view.setCellInput(0, 0, '100')");
    await view(page, 'view.setReadOnly(true)');
    await expect(input(page)).toHaveAttribute('readonly', '');
    await select(page, 'B8');
    await page.keyboard.type('x');
    await page.keyboard.press('F2');
    await page.keyboard.press('Delete');
    expect(await view(page, '[view.isEditing, view.undo(), view.history.canUndo]')).toEqual([false, false, true]);
    expect((await cell(page, 'A1')).value).toBe(100);
    expect(await events(page, 'change')).toHaveLength(1);

    await view(page, 'view.setReadOnly(false)');
    await expect(input(page)).not.toHaveAttribute('readonly', '');
    await page.keyboard.type('x');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'B8')).value).toBe('x');
    expect(await view(page, '[view.undo(), view.undo(), view.readOnly]')).toEqual([true, true, false]);
    expect((await cell(page, 'A1')).value).toBe(1);
  });

  test('a read-only view starts no edit from a composition', async ({ page }) => {
    await mount(page, await editWorkbook(), { readOnly: true });
    await focusGrid(page);
    await select(page, 'A2');
    const editing = await page.evaluate(() => {
      const element = document.querySelector('.bym-input') as HTMLTextAreaElement;
      element.dispatchEvent(new CompositionEvent('compositionstart', { bubbles: true, data: '' }));
      element.dispatchEvent(new InputEvent('input', { bubbles: true, isComposing: true, inputType: 'insertCompositionText', data: 'x' }));
      return (window as any).__view.isEditing;
    });
    expect(editing).toBe(false);
    expect(await editorState(page)).toMatchObject({ opacity: '0', mode: 'none' });
    expect((await cell(page, 'A2')).value).toBe('hello');
  });

  test('a dependant of a shared formula is edited as its own formula', async ({ page }) => {
    await mount(page, await reviewWorkbook());
    await focusGrid(page);
    await select(page, 'F3');
    await page.keyboard.press('F2');
    expect((await editorState(page)).value).toBe('=A3*2');
    // Confirmed unchanged, it stays what it was.
    await page.keyboard.press('Enter');
    expect(await events(page, 'change')).toEqual([]);

    await page.keyboard.press('F2');
    expect((await editorState(page)).value).toBe('=A4*2');
    await page.keyboard.type('+1');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'F4')).formula).toBe('A4*2+1');
    expect(await events(page, 'change')).toHaveLength(1);
  });

  test('Escape in the editor and in the menu stays inside the view', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await page.evaluate(() => {
      (window as any).__escapes = 0;
      document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') (window as any).__escapes++;
      });
    });
    await page.keyboard.type('x');
    await page.keyboard.press('Escape');
    expect(await view(page, 'view.isEditing')).toBe(false);

    const box = await canvasBox(page);
    expect(await contextMenuAt(page, box.x + HEADER_WIDTH / 2, pointIn(box, 2, 0).y)).toBe(true);
    await expect(page.locator('.bym-menu button').first()).toBeFocused();
    await page.keyboard.press('Escape');
    await expect(page.locator('.bym-menu')).toHaveCount(0);
    await expect(input(page)).toBeFocused();
    expect(await page.evaluate(() => (window as any).__escapes)).toBe(0);

    // With neither open, Escape is nobody's and passes through.
    await page.keyboard.press('Escape');
    expect(await page.evaluate(() => (window as any).__escapes)).toBe(1);
  });

  test('opening the header menu writes the open edit', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    await page.keyboard.type('before the menu');
    const box = await canvasBox(page);
    await contextMenuAt(page, box.x + HEADER_WIDTH / 2, pointIn(box, 2, 0).y);
    await expect(page.locator('.bym-menu')).toBeVisible();
    expect(await view(page, 'view.isEditing')).toBe(false);
    expect((await cell(page, 'B8')).value).toBe('before the menu');
    await page.keyboard.press('Escape');
  });
});

test.describe('review: focus', () => {
  test('a press on the empty part of the tab strip leaves the keyboard with the grid', async ({ page, hasTouch }) => {
    test.skip(!!hasTouch, MOUSE_ONLY);
    await mount(page, await editWorkbook());
    await focusGrid(page);
    const strip = (await page.locator('.bym-tabs').boundingBox())!;
    const lastTab = (await page.locator('.bym-tabs button').last().boundingBox())!;
    const x = strip.x + strip.width - 12;
    expect(x, 'there is room beside the tabs').toBeGreaterThan(lastTab.x + lastTab.width + 5);
    await page.mouse.click(x, strip.y + strip.height / 2);
    await expect(input(page)).toBeFocused();
    await page.keyboard.press('ArrowDown');
    expect(await selection(page)).toEqual({ active: 'A2', range: 'A2' });

    // The same from nowhere: the grid takes the focus.
    await page.locator('#after').focus();
    await page.mouse.click(x, strip.y + strip.height / 2);
    await expect(input(page)).toBeFocused();

    // An edit survives it too.
    await page.keyboard.type('still here');
    await page.mouse.click(x, strip.y + strip.height / 2);
    expect(await editorState(page)).toMatchObject({ editing: true, value: 'still here' });
    await page.keyboard.press('Escape');
  });

  test('focus that lands on the scrolling element goes back to the input without ending an edit', async ({ page }) => {
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await page.keyboard.type('abc');
    await page.evaluate(() => (document.querySelector('.bym-scroller') as HTMLElement).focus());
    await expect(input(page)).toBeFocused();
    expect(await editorState(page)).toMatchObject({ editing: true, value: 'abc' });
    await page.keyboard.press('Enter');
    expect((await cell(page, 'A1')).value).toBe('abc');
  });
});

test.describe('review: clipboard', () => {
  test('only this view\'s own copy is pasted as cells; the same text from elsewhere is typed in', async ({ page }) => {
    await mount(page, await reviewWorkbook());
    await focusGrid(page);
    await select(page, 'C3');
    const copy = await clipboardEvent(page, 'copy');
    expect(copy.text).toBe('3');
    expect(copy.html).toMatch(/^<table data-bym-copy="[a-z0-9]+">/);

    // Plain "3" from another program.
    await select(page, 'C10');
    await clipboardEvent(page, 'paste', '3');
    expect(await cell(page, 'C10')).toMatchObject({ kind: 'number', value: 3 });
    expect((await cell(page, 'C10')).formula).toBeUndefined();

    // "3" copied in another view: its HTML carries another mark.
    await select(page, 'C11');
    await clipboardEvent(page, 'paste', '3', '<table data-bym-copy="someoneelse"><tr><td>3</td></tr></table>');
    expect((await cell(page, 'C11')).formula).toBeUndefined();
    await clipboardEvent(page, 'paste', '3', '<table><tr><td>3</td></tr></table>');
    expect((await cell(page, 'C11')).formula).toBeUndefined();

    // The copy itself, as browsers hand it back (wrapped in more markup).
    await select(page, 'C12');
    await clipboardEvent(page, 'paste', '3', `<meta charset="utf-8"><!--StartFragment-->${copy.html}<!--EndFragment-->`);
    expect((await cell(page, 'C12')).formula).toBe('A10+A11');

    // From code: text alone is outside text.
    await select(page, 'C13');
    await page.evaluate(() => (window as any).__view.paste('3'));
    expect((await cell(page, 'C13')).formula).toBeUndefined();
    await page.evaluate((html) => (window as any).__view.paste('3', html), copy.html);
    expect((await cell(page, 'C13')).formula).toBe('A11+A12');

    // A later copy replaces the mark: the old HTML is no longer this view's copy.
    await select(page, 'A1');
    const second = await clipboardEvent(page, 'copy');
    expect(second.html).not.toBe(copy.html);
    await select(page, 'C14');
    await clipboardEvent(page, 'paste', '3', copy.html);
    expect((await cell(page, 'C14')).formula).toBeUndefined();
  });

  test('pasting over a merged cell writes its first cell and leaves the covered ones alone', async ({ page }) => {
    await mount(page, await reviewWorkbook());
    await select(page, 'D8');
    await page.evaluate(() => (window as any).__view.paste('a\tb\tc\nd\te\tf'));
    expect([(await cell(page, 'D8')).value, (await cell(page, 'F8')).value, (await cell(page, 'F9')).value]).toEqual(['a', 'c', 'f']);
    expect([(await cell(page, 'E8')).value, (await cell(page, 'D9')).value, (await cell(page, 'E9')).value]).toEqual([undefined, undefined, undefined]);
    expect(await view(page, 'view.workbook.sheets[0].merges')).toEqual([{ top: 7, left: 3, bottom: 8, right: 4 }]);
  });

  test('a paste of more than a million cells is refused whole', async ({ page }) => {
    test.setTimeout(120_000);
    await mount(page, await editWorkbook());
    await focusGrid(page);
    await select(page, 'B8');
    const thrown = await page.evaluate(() => {
      (window as any).__huge = new Array(1_000_002).join('a\t');
      try {
        (window as any).__view.paste((window as any).__huge);
        return 'nothing';
      } catch (error) {
        return `${(error as Error).name}: ${(error as Error).message}`;
      }
    });
    expect(thrown).toBe('RangeError: Cannot paste more than 1000000 cells at once');

    // Through the clipboard the refusal is announced.
    const prevented = await page.evaluate(() => {
      const event = new Event('paste', { bubbles: true, cancelable: true });
      Object.defineProperty(event, 'clipboardData', { value: { getData: (type: string) => (type === 'text/plain' ? (window as any).__huge : '') } });
      document.querySelector('.bym-input')!.dispatchEvent(event);
      return event.defaultPrevented;
    });
    expect(prevented).toBe(true);
    await expect(live(page)).toHaveText('Cannot paste more than 1000000 cells at once');
    expect((await cell(page, 'B8')).value).toBeUndefined();
    expect(await events(page, 'change')).toEqual([]);
    expect(await view(page, 'view.history.canUndo')).toBe(false);
    expect(await selection(page)).toEqual({ active: 'B8', range: 'B8' });
  });
});

test.describe('review: touch', () => {
  test('two quick taps on neighbouring cells are two taps', async ({ page, hasTouch }) => {
    test.skip(!hasTouch, TOUCH_ONLY);
    await mount(page, await reviewWorkbook());
    const box = await canvasBox(page);
    // Two points 8 pixels apart on either side of the line between rows 2 and 3.
    const x = pointIn(box, 0, 1).x;
    const line = box.y + HEADER_HEIGHT + 2 * ROW_HEIGHT;
    const result = await page.evaluate(
      ([x, above, below]) => {
        const canvas = document.querySelector('.bym-canvas')!;
        const tap = (y: number, id: number) => {
          for (const type of ['pointerdown', 'pointerup']) {
            canvas.dispatchEvent(new PointerEvent(type, { pointerId: id, pointerType: 'touch', isPrimary: true, clientX: x, clientY: y, bubbles: true, cancelable: true }));
          }
        };
        tap(above, 41);
        tap(below, 42);
        const view = (window as any).__view;
        const neighbours = { editing: view.isEditing, active: view.selection.active };
        // The same cell twice does edit.
        tap(below, 43);
        return { neighbours, same: view.isEditing };
      },
      [x, line - 4, line + 4],
    );
    expect(result.neighbours).toEqual({ editing: false, active: { row: 2, col: 1 } });
    expect(result.same).toBe(true);
  });

  test('a double tap counts within a merged cell and not across a scroll or a change of sheet', async ({ page, hasTouch }) => {
    test.skip(!hasTouch, TOUCH_ONLY);
    await mount(page, await reviewWorkbook());
    const box = await canvasBox(page);
    const tap = (x: number, y: number, id: number) =>
      page.evaluate(
        ([x, y, id]) => {
          const canvas = document.querySelector('.bym-canvas')!;
          for (const type of ['pointerdown', 'pointerup']) {
            canvas.dispatchEvent(new PointerEvent(type, { pointerId: id, pointerType: 'touch', isPrimary: true, clientX: x, clientY: y, bubbles: true, cancelable: true }));
          }
        },
        [x, y, id],
      );
    // D8 and E9 are one merged cell.
    const d8 = pointIn(box, 7, 3);
    const e9 = pointIn(box, 8, 4);
    await tap(d8.x, d8.y, 51);
    await tap(e9.x, e9.y, 52);
    expect(await editorState(page)).toMatchObject({ editing: true, value: '8' });
    await view(page, 'view.cancelEditing()');

    // Tap, scroll, tap on the same spot: another cell is there now.
    const a2 = pointIn(box, 1, 0);
    await tap(a2.x, a2.y, 53);
    await page.evaluate(() => {
      const scroller = document.querySelector('.bym-scroller')!;
      scroller.scrollTop = 200;
      (window as any).__view.getViewState();
      scroller.scrollTop = 0;
      (window as any).__view.getViewState();
    });
    await tap(a2.x, a2.y, 54);
    expect(await view(page, 'view.isEditing')).toBe(false);
    await view(page, 'view.cancelEditing()');

    // Tap, other sheet and back, tap.
    await view(page, 'view.select({ top: 5, left: 5, bottom: 5, right: 5 })');
    await tap(a2.x, a2.y, 55);
    await view(page, 'view.setActiveSheet(1)');
    await view(page, 'view.setActiveSheet(0)');
    await tap(a2.x, a2.y, 56);
    expect(await view(page, 'view.isEditing')).toBe(false);
  });

  test('a long press opens the menu only for a finger that stays put', async ({ page }) => {
    await page.clock.install();
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    const x = box.x + HEADER_WIDTH / 2;
    const y = pointIn(box, 2, 0).y;
    const menu = page.locator('.bym-menu');

    // The finger moves: a scroll gesture.
    await touchEvent(page, 'pointerdown', x, y);
    await touchEvent(page, 'pointermove', x, y + 40);
    await page.clock.fastForward(2000);
    await expect(menu).toHaveCount(0);
    await touchEvent(page, 'pointercancel', x, y + 40);

    // The content moves under the finger.
    await touchEvent(page, 'pointerdown', x, y, 32);
    await page.evaluate(() => {
      document.querySelector('.bym-scroller')!.scrollTop = 80;
    });
    await page.clock.fastForward(2000);
    await expect(menu).toHaveCount(0);
    await touchEvent(page, 'pointerup', x, y, 32);
    await page.evaluate(() => {
      document.querySelector('.bym-scroller')!.scrollTop = 0;
      (window as any).__view.getViewState();
    });

    // The finger is lifted early.
    await touchEvent(page, 'pointerdown', x, y, 33);
    await page.clock.fastForward(200);
    await touchEvent(page, 'pointerup', x, y, 33);
    await page.clock.fastForward(2000);
    await expect(menu).toHaveCount(0);

    // On a cell it is the cell's menu.
    const cellPoint = pointIn(box, 2, 1);
    await touchEvent(page, 'pointerdown', cellPoint.x, cellPoint.y, 34);
    await page.clock.fastForward(2000);
    await expect(menu.locator('button').first()).toHaveText('Cut');
    await touchEvent(page, 'pointerup', cellPoint.x, cellPoint.y, 34);
    await page.keyboard.press('Escape');
    await expect(menu).toHaveCount(0);

    // It stays: the menu.
    await touchEvent(page, 'pointerdown', x, y, 35);
    await page.clock.fastForward(400);
    await expect(menu).toHaveCount(0);
    await page.clock.fastForward(400);
    await expect(menu).toHaveCount(1);
    await expect(menu.locator('button')).toHaveText(['Insert row above', 'Insert row below', 'Delete row']);
  });

  test('the menu of a real long press survives lifting the finger and takes a tap', async ({ page, browserName, hasTouch }) => {
    test.skip(!hasTouch || browserName !== 'chromium', 'real touch events can only be produced in Chromium, through the DevTools protocol');
    await mount(page, await editWorkbook());
    const box = await canvasBox(page);
    const x = Math.round(box.x + HEADER_WIDTH / 2);
    const y = Math.round(pointIn(box, 2, 0).y);
    const client = await page.context().newCDPSession(page);
    const menu = page.locator('.bym-menu');
    // Everything the browser sends for the gesture, in order.
    await page.evaluate(() => {
      (window as any).__seen = [];
      for (const type of ['pointerdown', 'pointerup', 'touchstart', 'touchend', 'mousedown', 'mouseup', 'click', 'contextmenu']) {
        document.addEventListener(type, () => (window as any).__seen.push(type), true);
      }
    });

    await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x, y }] });
    await expect(menu).toBeVisible();
    await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
    await expect.poll(() => page.evaluate(() => (window as any).__seen.includes('touchend'))).toBe(true);
    await twoFrames(page);
    await twoFrames(page);
    await expect(menu).toBeVisible();
    await expect(menu.locator('button')).toHaveText(['Insert row above', 'Insert row below', 'Delete row']);
    // Lifting the finger pressed nothing.
    expect(await events(page, 'change')).toEqual([]);
    expect(await rawRange(page)).toEqual({ top: 2, bottom: 2, left: 0, right: MAX_COLS - 1 });

    const item = (await menu.locator('button').nth(2).boundingBox())!;
    const point = { x: Math.round(item.x + item.width / 2), y: Math.round(item.y + item.height / 2) };
    await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [point] });
    await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
    await expect(menu).toHaveCount(0);
    await expect.poll(() => events(page, 'change')).toHaveLength(1);
    expect((await cell(page, 'A3')).value).toBeUndefined();
    expect((await cell(page, 'A2')).value).toBe('hello');
  });
});

test.describe('review: teardown', () => {
  test('destroy with the menu open and a long press pending leaves no listener and no timer', async ({ page }) => {
    await page.goto('/e2e/pages/view.html');
    await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
    await page.evaluate(() => {
      const ledger = { listeners: 0, onDocument: 0, timers: new Set<number>() };
      (window as any).__ledger = ledger;
      const live = new Map<EventTarget, Map<string, Set<unknown>>>();
      const add = EventTarget.prototype.addEventListener;
      const remove = EventTarget.prototype.removeEventListener;
      EventTarget.prototype.addEventListener = function (this: EventTarget, type: string, listener: any, options?: any) {
        if (listener) {
          let types = live.get(this);
          if (!types) live.set(this, (types = new Map()));
          let set = types.get(type);
          if (!set) types.set(type, (set = new Set()));
          if (!set.has(listener)) {
            set.add(listener);
            ledger.listeners++;
            if (this === document) ledger.onDocument++;
          }
        }
        return add.call(this, type, listener, options);
      };
      EventTarget.prototype.removeEventListener = function (this: EventTarget, type: string, listener: any, options?: any) {
        const set = live.get(this)?.get(type);
        if (set && set.delete(listener)) {
          ledger.listeners--;
          if (this === document) ledger.onDocument--;
        }
        return remove.call(this, type, listener, options);
      };
      const set = window.setTimeout.bind(window);
      const clear = window.clearTimeout.bind(window);
      (window as any).setTimeout = (handler: () => void, delay?: number) => {
        const id = set(() => {
          ledger.timers.delete(id);
          handler();
        }, delay);
        ledger.timers.add(id);
        return id;
      };
      (window as any).clearTimeout = (id: number) => {
        ledger.timers.delete(id);
        clear(id);
      };
    });

    const bytes = await editWorkbook();
    const result = await page.evaluate(async (base64) => {
      const ledger = (window as any).__ledger;
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountView(data, { locale: 'en-US' });
      // The view looks for formulas without a result in a turn of its own; that one is over before the count.
      await new Promise((resolve) => setTimeout(resolve, 30));
      const view = (window as any).__view;
      const canvas = document.querySelector('.bym-canvas') as HTMLCanvasElement;
      const box = canvas.getBoundingClientRect();
      const before = { onDocument: ledger.onDocument, timers: ledger.timers.size };

      // The menu, opened by a right click on the header of row 3.
      canvas.dispatchEvent(new MouseEvent('contextmenu', { clientX: box.left + 36, clientY: box.top + 22 + 50, button: 2, bubbles: true, cancelable: true }));
      const menuOpen = document.querySelectorAll('.bym-menu').length;
      const withMenu = ledger.onDocument;
      // A finger resting on the canvas: the long press is counting.
      canvas.dispatchEvent(new PointerEvent('pointerdown', { pointerId: 61, pointerType: 'touch', isPrimary: true, clientX: box.left + 36, clientY: box.top + 22 + 90, bubbles: true, cancelable: true }));
      const withTouch = ledger.timers.size;
      // And an edit.
      view.select({ top: 7, left: 1, bottom: 7, right: 1 });
      view.startEditing('open');

      view.destroy();
      return {
        before,
        menuOpen,
        menuListeners: withMenu - before.onDocument,
        touchTimers: withTouch - before.timers,
        listenersLeft: ledger.listeners,
        onDocumentLeft: ledger.onDocument - before.onDocument,
        timersLeft: ledger.timers.size - before.timers,
        menus: document.querySelectorAll('.bym-menu').length,
        hostChildren: document.getElementById('host')!.children.length,
      };
    }, Buffer.from(bytes).toString('base64'));

    expect(result.menuOpen).toBe(1);
    expect(result.menuListeners, 'the open menu listens on the document').toBeGreaterThan(0);
    expect(result.touchTimers, 'the long press timer is running').toBe(1);
    expect(result).toMatchObject({ listenersLeft: 0, onDocumentLeft: 0, timersLeft: 0, menus: 0, hostChildren: 0 });
  });
});

// ---------------------------------------------------------------------------
// Formulas are calculated as the sheet is edited.

test.describe('calculation', () => {
  test('dependants of a shared formula whose master was overwritten keep calculating', async ({ page }) => {
    await mount(page, await reviewWorkbook());
    await view(page, "view.setCellInput(2, 0, '7')");
    expect((await cell(page, 'F3')).value).toBe(14);
    // F2 was the master of F2:F4; F3 and F4 now hold the formula themselves.
    await view(page, "view.setCellInput(1, 5, '100')");
    await view(page, "view.setCellInput(2, 0, '9')");
    expect((await cell(page, 'F3')).value).toBe(18);
    await view(page, 'view.undo()');
    expect((await cell(page, 'F3')).value).toBe(14);
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect((await cell(page, 'F3')).value).toBe(0);
    expect((await cell(page, 'F2')).value).toBe(4);
  });

  test('a change is calculated through formulas and undone with it', async ({ page }) => {
    await mount(page, await reviewWorkbook());
    await view(page, "view.setCellInput(0, 0, '10')");
    expect((await cell(page, 'C3')).value).toBe(12);
    await view(page, "view.setCellInput(6, 0, '=SUM(A1:A2)*C3')");
    expect((await cell(page, 'A7')).value).toBe(144);
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect((await cell(page, 'C3')).value).toBe(3);
    await view(page, 'view.redo()');
    await view(page, 'view.redo()');
    expect((await cell(page, 'A7')).value).toBe(144);
  });

  test('deleting a row recalculates the sums that lost it, although their inputs kept their values', async ({ page }) => {
    const bytes = await buildXlsx({
      sheets: [
        {
          name: 'Sum',
          xml: worksheetXml(
            `<sheetData><row r="1">${num('A1', 1)}</row><row r="2">${num('A2', 2)}</row><row r="3">${num('A3', 4)}</row>` +
              '<row r="4"><c r="A4"><f>SUM(A1:A3)</f><v>7</v></c><c r="B4"><f>A2*10</f></c></row></sheetData>',
          ),
        },
      ],
    });
    await mount(page, bytes);
    // B4 came without a result; it is calculated once the view is up.
    await expect.poll(async () => (await cell(page, 'B4')).value).toBe(20);
    expect((await cell(page, 'A4')).value).toBe(7);
    await view(page, 'view.deleteRows(1, 1)');
    expect((await cell(page, 'A3')).value).toBe(5);
    await view(page, 'view.undo()');
    expect((await cell(page, 'A4')).value).toBe(7);
  });

  test('a formula that cannot be read keeps the editor open and says why', async ({ page }) => {
    await mount(page, await reviewWorkbook());
    await focusGrid(page);
    await select(page, 'B1');
    await page.keyboard.type('=SUM(A1;A2)');
    await page.keyboard.press('Enter');
    expect((await editorState(page)).editing).toBe(true);
    await expect(live(page)).toHaveText(/formula cannot be read/);
    expect((await cell(page, 'B1')).formula).toBeUndefined();
    await page.keyboard.press('Escape');
    await page.keyboard.type('=SUM(A1,A2)');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'B1')).value).toBe(3);
  });
});
